-- ===========================================================================
-- Schedule C, the inventory checklist, per residence (28 Oct 2026).
--
-- The Arc's form and Solstice's list different rooms and items. The list was
-- one list in the code (inventory.ts), so every residence was asked The Arc's.
-- Now it is the residence's own, set in Admin > Website > Residences >
-- Schedule C:
--   {"brands": [...], "areas": [{"id", "name", "items": [{"id", "name", "qty",
--     "details": "brand" | "serial" | ["choice", ...] | null}]}]}
-- A check keeps the list it was sent with (record.list); one sent before
-- today has none and is read with The Arc's form of 1 Oct 2026.
--
-- Filled once: The Arc with that form (same item ids, so the records already
-- made read the same), Solstice with its sample inventory (ST1-09-04) - the
-- brand is picked on each "brand" row, as at The Arc. Only where still empty.
-- Safe to run again.
-- ===========================================================================

alter table public.residences
  add column if not exists inventory jsonb not null default '{}'::jsonb;

